import test from 'node:test';
import assert from 'node:assert/strict';
import { DatabaseSync } from 'node:sqlite';
import { handleShareRequest, shareSchema, inspectSharedPng, inspectSharedImage } from '../server/shares.mjs';

// A complete, valid 2x1 PNG generated by a real PNG encoder.
const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAIAAAABCAYAAAD0In+KAAAADUlEQVR42mNk+P+/HgAFhAJ/wRZeOQAAAABJRU5ErkJggg==', 'base64');
function fixture(t) {
  const sqlite = new DatabaseSync(':memory:');
  t.after(() => sqlite.close());
  sqlite.exec(`CREATE TABLE users (id TEXT PRIMARY KEY, status TEXT); CREATE TABLE user_sessions (token TEXT, user_id TEXT, expires_at INTEGER); ${shareSchema};`);
  for (const id of ['owner', 'other', 'usr_guest_trial']) {
    sqlite.prepare('INSERT INTO users VALUES (?,?)').run(id, 'active');
    sqlite.prepare('INSERT INTO user_sessions VALUES (?,?,?)').run(id, id, Date.now() + 86400000);
  }
  const db = { prepare(sql) {
    let values = [];
    const statement = { bind(...args) { values = args; return statement; },
      async run() { const result = sqlite.prepare(sql).run(...values); return { meta: { changes: Number(result.changes) } }; },
      async first() { return sqlite.prepare(sql).get(...values) || null; },
      async all() { return { results: sqlite.prepare(sql).all(...values) }; },
    };
    return statement;
  } };
  const objects = new Map(), metadata = new Map();
  const storage = { async put(key, bytes, options) { objects.set(key, new Uint8Array(bytes)); metadata.set(key, options?.metadata); }, async delete(key) { objects.delete(key); },
    async get(key) { const data = objects.get(key); return data ? new ReadableStream({ start(c) { c.enqueue(data); c.close(); } }) : null; } };
  storage.getWithMetadata = async key => ({ value: await storage.get(key), metadata: metadata.get(key) || null });
  const call = async (path = '', { token = 'owner', body, method = body === undefined ? 'GET' : 'POST', headers = {} } = {}) => {
    const response = await handleShareRequest({ db, storage, request: new Request(`https://studio.example/api/shares${path}`, {
      method, headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}), ...headers },
      ...(body === undefined ? {} : { body: typeof body === 'object' && !ArrayBuffer.isView(body) ? JSON.stringify(body) : body }),
    }) });
    return { response, data: response.headers.get('Content-Type')?.startsWith('application/json') ? await response.json() : null };
  };
  const create = (options, listed = false) => call(`?title=Alpine%20lake&allowDownload=1${listed ? '&listed=1' : ''}`, { body: png, headers: { 'Content-Type': 'image/png' }, ...options });
  return { db, sqlite, storage, objects, metadata, call, create };
}

test('showcase listing is opt-in, anonymous, and reversible', async t => {
  const f = fixture(t);
  const privateShare = await f.create();
  const publicShare = await f.create({}, true);
  assert.equal(privateShare.data.share.listed, false);
  assert.equal(publicShare.data.share.listed, true);
  assert.equal((await f.call('/' + publicShare.data.share.id, { token: null })).data.share.listed, true);

  // A private share never leaks into the anonymous feed, even to its own owner.
  const feed = await f.call('?public=1', { token: null });
  assert.equal(feed.response.status, 200);
  assert.deepEqual(feed.data.shares.map(row => row.id), [publicShare.data.share.id]);
  assert.deepEqual(Object.keys(feed.data.shares[0]).sort(), ['createdAt', 'height', 'id', 'title', 'width']);

  const mine = (await f.call('')).data.shares;
  assert.equal(mine.find(row => row.id === publicShare.data.share.id).listed, true);
  assert.equal(mine.find(row => row.id === privateShare.data.share.id).listed, false);

  const id = publicShare.data.share.id;
  assert.equal((await f.call('/' + id, { token: 'other', body: { listed: false } })).response.status, 404);
  assert.equal((await f.call('/' + id, { body: { listed: false } })).response.status, 200);
  assert.equal((await f.call('?public=1', { token: null })).data.shares.length, 0);
  await f.call('/' + id, { body: { listed: true } });
  assert.equal((await f.call('?public=1', { token: null })).data.shares.length, 1);
  await f.call('/' + id, { body: { action: 'revoke' } });
  assert.equal((await f.call('?public=1', { token: null })).data.shares.length, 0);
});

test('share tables created before the showcase flag gain the listing column', async t => {
  const f = fixture(t);
  f.sqlite.exec('ALTER TABLE panorama_shares DROP COLUMN listed');
  assert.equal((await f.create()).data.share.listed, false);
  assert.equal((await f.create({}, true)).data.share.listed, true);
  assert.equal(f.sqlite.prepare('SELECT COUNT(*) AS n FROM panorama_shares WHERE listed = 1').get().n, 1);
  assert.equal((await f.call('?public=1', { token: null })).data.shares.length, 1);
});

test('share lifecycle: create, anonymous interaction image, download toggle, ownership and revocation', async t => {
  const f = fixture(t);
  const created = await f.create();
  assert.equal(created.response.status, 201);
  const id = created.data.share.id;
  assert.match(id, /^[a-f0-9]{32}$/);
  const publicMeta = await f.call('/' + id, { token: null });
  assert.equal(publicMeta.data.share.title, 'Alpine lake');
  assert.equal(publicMeta.data.share.owner_id, undefined);
  const image = await f.call(`/${id}/image`, { token: null });
  assert.equal(image.response.status, 200);
  assert.deepEqual(Buffer.from(await image.response.arrayBuffer()), png);
  assert.equal(image.response.headers.get('Cache-Control'), 'no-store');
  assert.equal((await f.call(`/${id}/download`, { token: null })).response.status, 200);
  assert.equal((await f.call('/' + id, { token: 'other', body: { action: 'revoke' } })).response.status, 404);
  assert.equal((await f.call('/' + id, { body: { allowDownload: false } })).response.status, 200);
  assert.equal((await f.call(`/${id}/download`, { token: null })).response.status, 403);
  assert.equal((await f.call(`/${id}/image`, { token: null })).response.status, 200);
  assert.equal((await f.call('', { token: 'other' })).data.shares.length, 0);
  await f.call('/' + id, { body: { action: 'revoke' } });
  // Simulate stale KV bytes: D1 revocation must deny every public endpoint anyway.
  f.objects.set(`panorama:${id}`, png);
  for (const suffix of ['', '/image', '/download']) assert.equal((await f.call(`/${id}${suffix}`, { token: null })).response.status, 404);
  assert.equal((await f.call('')).data.shares[0].revoked, true);
});

test('only an active permanent session may publish or manage', async t => {
  const f = fixture(t);
  assert.equal((await f.create({ token: null })).response.status, 401);
  assert.equal((await f.create({ token: 'bad' })).response.status, 401);
  assert.equal((await f.create({ token: 'usr_guest_trial' })).response.status, 403);
  f.sqlite.exec("UPDATE users SET status = 'suspended' WHERE id = 'owner'");
  assert.equal((await f.create()).response.status, 403);
  assert.equal(f.objects.size, 0);
});

test('upload validation rejects wrong types, malformed/truncated PNG, wrong geometry and oversized bodies', async t => {
  const f = fixture(t);
  assert.equal((await f.create({ headers: { 'Content-Type': 'image/svg+xml' } })).response.status, 415);
  assert.equal((await f.create({ body: Buffer.from('<svg></svg>') })).response.status, 400);
  assert.equal((await f.create({ body: png.subarray(0, png.length - 4) })).response.status, 400);
  const wrong = Buffer.from(png); wrong.writeUInt32BE(3, 16);
  assert.equal((await f.create({ body: wrong })).response.status, 400);
  assert.equal((await f.create({ headers: { 'Content-Type': 'image/png', 'Content-Length': String(21 * 1024 * 1024) } })).response.status, 413);
  assert.equal((await f.call('?title=' + 'a'.repeat(101), { body: png, headers: { 'Content-Type': 'image/png' } })).response.status, 400);
  assert.equal(f.objects.size, 0);
});

test('failed storage publishes no link and releases its reserved quota', async t => {
  const f = fixture(t);
  f.storage.put = async () => { throw new Error('simulated outage'); };
  assert.equal((await f.create()).response.status, 503);
  assert.equal(f.sqlite.prepare('SELECT COUNT(*) AS n FROM panorama_shares').get().n, 0);
  assert.equal(f.objects.size, 0);
});

test('daily publishing quota is atomic across concurrent requests', async t => {
  const f = fixture(t);
  const responses = await Promise.all(Array.from({ length: 7 }, () => f.create()));
  assert.equal(responses.filter(r => r.response.status === 201).length, 5);
  assert.equal(responses.filter(r => r.response.status === 429).length, 2);
  assert.equal(f.objects.size, 5);
});

test('missing KV replicas return a retryable response rather than a broken successful image', async t => {
  const f = fixture(t); const id = (await f.create()).data.share.id;
  f.objects.clear();
  const result = await f.call(`/${id}/image`, { token: null });
  assert.equal(result.response.status, 503);
  assert.equal(result.response.headers.get('Retry-After'), '5');
});

test('PNG signature validator accepts a full 2:1 image and rejects empty data', () => {
  assert.deepEqual(inspectSharedPng(png), { width: 2, height: 1 });
  assert.throws(() => inspectSharedPng(new Uint8Array()), /PNG/);
});


const jpeg = Buffer.from([255,216,255,192,0,11,8,0,1,0,2,1,1,17,0,255,218,0,8,1,1,0,0,63,0,18,255,217]);
test('compressed JPEG shares retain MIME, dimensions and correct download extension', async t => {
  const f = fixture(t);
  assert.deepEqual(inspectSharedImage(jpeg, 'image/jpeg'), { width: 2, height: 1 });
  const created = await f.create({ body: jpeg, headers: { 'Content-Type': 'image/jpeg' } });
  assert.equal(created.response.status, 201);
  const image = await f.call(`/${created.data.share.id}/download`, { token: null });
  assert.equal(image.response.headers.get('Content-Type'), 'image/jpeg');
  assert.match(image.response.headers.get('Content-Disposition'), /\.jpg"$/);
  assert.deepEqual(Buffer.from(await image.response.arrayBuffer()), jpeg);
  assert.equal((await f.create({ body: png, headers: { 'Content-Type': 'image/jpeg' } })).response.status, 400);
  assert.equal((await f.create({ body: jpeg.subarray(0, -2), headers: { 'Content-Type': 'image/jpeg' } })).response.status, 400);
});

test('pre-compression PNG shares without stored MIME metadata remain accessible', async t => {
  const f = fixture(t); const id = (await f.create()).data.share.id;
  f.metadata.clear();
  const image = await f.call(`/${id}/image`, { token: null });
  assert.equal(image.response.status, 200);
  assert.equal(image.response.headers.get('Content-Type'), 'image/png');
  assert.equal((await f.call('/', { token: 'owner' })).response.status, 200);
});

test('share storage budgets apply across owners and keep failed deletion capacity reserved',async t=>{
 const f=fixture(t);const created=await f.create();const id=created.data.share.id;
 f.sqlite.prepare('UPDATE panorama_shares SET stored_bytes = ?').run(100*1024*1024);
 assert.equal((await f.create()).response.status,429);
 f.sqlite.prepare('UPDATE panorama_shares SET stored_bytes = ?, owner_id = ?').run(128*1024*1024,'other');
 assert.equal((await f.create()).response.status,429);
 f.storage.delete=async()=>{throw Error('storage unavailable');};
 await f.call('/'+id,{token:'other',body:{action:'revoke'}});
 assert.equal((await f.call('/'+id+'/image',{token:null})).response.status,404);
 assert.equal(f.sqlite.prepare('SELECT stored_bytes FROM panorama_shares WHERE id = ?').get(id).stored_bytes,128*1024*1024);
});
